self.addEventListener("push",t=>{let i={title:"Airoma",body:"Un petit rappel pour tes objectifs.",url:"/dashboard"};try{t.data&&(i={...i,...t.data.json()})}catch{t.data&&(i.body=t.data.text())}t.waitUntil(self.registration.showNotification(i.title,{body:i.body,icon:"/icons/icon-192.png",badge:"/icons/icon-192.png",data:{url:i.url||"/dashboard"},lang:"fr"}))}),self.addEventListener("notificationclick",t=>{t.notification.close();let i=t.notification.data?.url||"/dashboard";t.waitUntil(self.clients.matchAll({type:"window",includeUncontrolled:!0}).then(t=>{for(let n of t)if("focus"in n)return n.navigate(i),n.focus();if(self.clients.openWindow)return self.clients.openWindow(i)}))});